package com.watchalign.mobile;
import android.content.Context;import android.content.Intent;import android.graphics.*;import androidx.core.content.FileProvider;import java.io.*;import java.text.DateFormat;import java.util.Date;
final class QcExport {
 static void share(Context c,Bitmap watch,String model,String summary)throws Exception{int w=watch.getWidth(),footer=Math.max(300,w/3);Bitmap out=Bitmap.createBitmap(w,watch.getHeight()+footer,Bitmap.Config.ARGB_8888);Canvas x=new Canvas(out);x.drawColor(Color.rgb(8,17,31));x.drawBitmap(watch,0,0,new Paint(Paint.FILTER_BITMAP_FLAG));Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.WHITE);p.setTextSize(Math.max(22,w/38f));p.setFakeBoldText(true);float y=watch.getHeight()+p.getTextSize()*1.5f;x.drawText("WATCH ALIGN QC · "+model,24,y,p);p.setFakeBoldText(false);p.setTextSize(Math.max(17,w/52f));y+=p.getTextSize()*1.6f;for(String line:summary.split("\n")){for(String wrapped:wrap(line,64)){x.drawText(wrapped,24,y,p);y+=p.getTextSize()*1.25f;if(y>out.getHeight()-20)break;}}File dir=new File(c.getCacheDir(),"shared");dir.mkdirs();File f=new File(dir,"watch-align-qc-"+System.currentTimeMillis()+".jpg");try(FileOutputStream stream=new FileOutputStream(f)){out.compress(Bitmap.CompressFormat.JPEG,94,stream);}out.recycle();Intent i=new Intent(Intent.ACTION_SEND);i.setType("image/jpeg");i.putExtra(Intent.EXTRA_STREAM,FileProvider.getUriForFile(c,c.getPackageName()+".files",f));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);c.startActivity(Intent.createChooser(i,"Share Watch Align QC"));}
 private static String[] wrap(String s,int n){if(s.length()<=n)return new String[]{s};java.util.List<String>o=new java.util.ArrayList<>();while(s.length()>n){int k=s.lastIndexOf(' ',n);if(k<1)k=n;o.add(s.substring(0,k));s=s.substring(k).trim();}o.add(s);return o.toArray(new String[0]);}private QcExport(){}
}
